shellCommands.command:
f=src/orders/OrdersTable.tsx && node - "$f" <<'EOF'
const fs=require('fs');const f=process.argv[2];let s=fs.readFileSync(f,'utf8');
const old=`                        rowClassName={(row) =>
                            row?.getIsSelected() && row.original.kind === 'order'
                                ? 'orders-table__row orders-table__row_selected'
                                : 'orders-table__row'
                        }`;
const neu=`                        rowClassName={getRowClassName}
                        cellClassName={getPinnedClassName}
                        headerCellClassName={getPinnedClassName}`;
if(!s.includes(old)) throw 'no match';
s=s.replace(old,neu);
const anchor='/** Adds group ids to the selection';
s=s.replace(anchor,`function getRowClassName(row?: Row<OrderRow>) {
    if (!row) return '';
    if (row.original.kind === 'group') return 'orders-table__group-row';
    return row.getIsSelected()
        ? 'orders-table__row orders-table__row_selected'
        : 'orders-table__row';
}

/** Pinned (sticky) cells need an opaque background so scrolled cells don't show through. */
function getPinnedClassName(item?: {column: {getIsPinned: () => false | 'left' | 'right'}}) {
    return item?.column.getIsPinned() ? 'orders-table__pinned-cell' : '';
}

`+anchor);
s=s.replace(`<Flex alignItems="center" gap={3} className="orders-table__group">`,`<Flex alignItems="center" gap={3}>`);
fs.writeFileSync(f,s);
EOF
node - src/App.css <<'EOF'
const fs=require('fs');const f=process.argv[2];let s=fs.readFileSync(f,'utf8');
s=s.replace(/\.orders-table__group \{[\s\S]*?\n\}\n/,`.orders-table__group-row {
    background: var(--g-color-base-generic);
}

/* Sticky selection column: opaque base + the row state layered on top. */
.orders-table__pinned-cell {
    background-color: var(--g-color-base-background);
}

.orders-table__row:hover .orders-table__pinned-cell {
    background-image: linear-gradient(var(--g-color-base-simple-hover), var(--g-color-base-simple-hover));
}

.orders-table__row_selected .orders-table__pinned-cell,
.orders-table__row_selected:hover .orders-table__pinned-cell {
    background-image: linear-gradient(var(--g-color-base-selection), var(--g-color-base-selection));
}
`);
fs.writeFileSync(f,s);
EOF
